@router.get("/admin/overview")
def admin_overview(ident: Identity = Depends(identity.identify)) -> dict[str, Any]:
    """开发后台只读总览：运行态 + 规则/技能/接口契约（编译进项目的数据文件），仅 developer。"""
    identity.require_role(ident, "developer")
    return {
        "project": settings.project,
        "pack_ref": settings.pack_ref,
        "redis": session_service.redis_ping(),
        "languages": sorted(i18n.MESSAGES),
        "model_configured": bool(
            settings.model_base_url and settings.model_name and settings.model_api_key
        ),
        "core_mode": settings.core_mode,
        "business_console": settings.business_console,
        "auth_mode": "hmac" if not identity.dev_mode() else "debug(未配 IW_AUTH_SECRET，免签仅调试)",
        "rules": rule_engine.load_rules(),
        "skills": _read_data_json("skills.json"),
        "apis": _read_data_json("apis.json"),
    }


def _require_console() -> None:
    if not settings.business_console:
        raise HTTPException(status_code=404, detail="业务后台未开启")


@router.get("/console", include_in_schema=False)
def console(ident: Identity = Depends(identity.identify)) -> FileResponse:
    _require_console()
    identity.require_role(ident, "developer", "agent")
    return FileResponse(STATIC_DIR / "console.html")


@router.get("/console/sessions")
def console_sessions(ident: Identity = Depends(identity.identify)) -> list[dict[str, Any]]:
    """业务后台会话列表：仅返回被规则打标的会话；agent 只见本组，developer 见全部。"""
    _require_console()
    identity.require_role(ident, "developer", "agent")
    rows = []
    for item in session_service.list_sessions():
        slots = item["slots"]
        if not slots.get("flagged"):
            continue
        owner = session_service.get_json("sess:%s" % item["session_id"]) or {}
        if ident.role == "agent" and owner.get("group") != ident.group:
            continue
        rows.append(
            {
                "session_id": item["session_id"],
                "flagged": slots["flagged"],
                "turns": slots.get("turns", 0),
                "user": owner.get("user", ""),
                "group": owner.get("group", ""),
            }
        )
    return rows
